from collections import deque
A=[[0,5,0,0,0,0,0,5,0,0,5,0],[0,5,0,0,0,5,5,5,0,5,5,0],[5,5,5,0,0,5,0,5,5,5,0,0],[0,0,5,5,5,5,0,5,0,5,5,0],[0,0,0,5,0,0,0,5,0,0,5,0]]
R,C=len(A),len(A[0]); seen=set(); comps=[]
for r in range(R):
 for c in range(C):
  if A[r][c] or (r,c) in seen: continue
  q=deque([(r,c)]);seen.add((r,c));g=[]
  while q:
   x,y=q.popleft();g.append((x,y))
   for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
    xx,yy=x+dx,y+dy
    if 0<=xx<R and 0<=yy<C and A[xx][yy]==0 and (xx,yy) not in seen: seen.add((xx,yy));q.append((xx,yy))
  comps.append(g)
print(sorted([(len(g),g) for g in comps], key=lambda z:z[0]))
small=min(map(len,comps)); large=max(map(len,comps)); print('min,max',small,large,'countties',sum(len(g)==small for g in comps),sum(len(g)==large for g in comps))
B=[row[:] for row in A]
for g in comps:
 if len(g)==small:
  for x,y in g:B[x][y]=7
 if len(g)==large:
  for x,y in g:B[x][y]=8
print(B)
print('valid',len(B),all(len(x)==C for x in B),set(v for r in B for v in r))
